CREATE DATABASE `leyanxiu_xpay_production` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_environment` (id INTEGER PRIMARY KEY, app_id VARCHAR(80) NOT NULL, env INTEGER NOT NULL, CHECK(id = 1), CHECK(env IN (0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_accounts` (user_id VARCHAR(80) PRIMARY KEY, app_id VARCHAR(80) NOT NULL, openid VARCHAR(128) NOT NULL, UNIQUE(app_id, openid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_sessions` (id VARCHAR(80) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, sealed LONGTEXT NOT NULL, expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_orders` (id VARCHAR(32) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, idem VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, provider_id VARCHAR(128) UNIQUE, payload LONGTEXT NOT NULL, created_at BIGINT NOT NULL, checked_at BIGINT NOT NULL DEFAULT 0, UNIQUE(user_id, idem)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_buckets` (id VARCHAR(100) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, order_id VARCHAR(32) NOT NULL, kind VARCHAR(16) NOT NULL, starts_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, quantity INTEGER NOT NULL, remaining INTEGER NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, frozen INTEGER NOT NULL DEFAULT 0, value_fen INTEGER NOT NULL, CHECK(remaining >= 0), CHECK(reserved >= 0), CHECK(frozen >= 0), CHECK(remaining + reserved + frozen <= quantity)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_reservations` (id VARCHAR(128) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, bucket_id VARCHAR(100) NOT NULL, purpose VARCHAR(100) NOT NULL, status VARCHAR(32) NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_refunds` (id VARCHAR(32) PRIMARY KEY, order_id VARCHAR(32) NOT NULL UNIQUE, user_id VARCHAR(80) NOT NULL, status VARCHAR(32) NOT NULL, payload LONGTEXT NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_events` (id VARCHAR(160) PRIMARY KEY, order_id VARCHAR(32) NOT NULL, digest VARCHAR(64) NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_outbox` (id VARCHAR(80) PRIMARY KEY, order_id VARCHAR(32) NOT NULL, kind VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_audit` (id VARCHAR(32) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, action VARCHAR(64) NOT NULL, reference_id VARCHAR(128) NOT NULL, detail LONGTEXT NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_reconciliation` (id VARCHAR(32) PRIMARY KEY, payload LONGTEXT NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_schema` (version INTEGER PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`vp_auth_sessions` (
    id VARCHAR(80) PRIMARY KEY,
    user_id VARCHAR(80) NOT NULL,
    app_id VARCHAR(80) NOT NULL,
    token_hash CHAR(64) NOT NULL UNIQUE,
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    revoked_at BIGINT,
    CHECK(expires_at - created_at = 86400000),
    FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id),
    INDEX vp_auth_sessions_user (user_id, expires_at)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_accounts` (user_id VARCHAR(80) PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1,
      consent_epoch INTEGER NOT NULL DEFAULT 0, basic_version VARCHAR(80), face_version VARCHAR(80), subject_authorization VARCHAR(16),
      updated_at BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id), CHECK(enabled IN (0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_effects` (effect_id VARCHAR(80) NOT NULL, version VARCHAR(80) NOT NULL,
      provider VARCHAR(80) NOT NULL, model VARCHAR(100) NOT NULL, purpose VARCHAR(100) NOT NULL, parameters LONGTEXT NOT NULL,
      enabled INTEGER NOT NULL, review_reference VARCHAR(128) NOT NULL, created_at BIGINT NOT NULL,
      PRIMARY KEY(effect_id,version), CHECK(enabled IN (0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_assets` (id VARCHAR(128) PRIMARY KEY, user_id VARCHAR(80) NOT NULL,
      kind VARCHAR(16) NOT NULL, state VARCHAR(16) NOT NULL, storage_key VARCHAR(512) NOT NULL UNIQUE,
      sha256 CHAR(64) NOT NULL, byte_length BIGINT NOT NULL, content_type VARCHAR(32) NOT NULL,
      consent_epoch INTEGER NOT NULL, job_id VARCHAR(80) UNIQUE, moderation_reference VARCHAR(128) NOT NULL,
      label_version VARCHAR(80), expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL,
      FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id), CHECK(kind IN ('input','output')),
      CHECK(state IN ('ready','staged','published','revoked','deleted'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_works` (job_id VARCHAR(80) PRIMARY KEY, asset_id VARCHAR(128) NOT NULL UNIQUE,
      user_id VARCHAR(80) NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id),
      FOREIGN KEY(asset_id) REFERENCES `leyanxiu_xpay_production`.`mini_photo_assets`(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_jobs` (
    id VARCHAR(80) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, idem VARCHAR(128) NOT NULL,
    spec LONGTEXT NOT NULL, spec_hash CHAR(64) NOT NULL,
    billing_ref VARCHAR(128) NOT NULL, state VARCHAR(24) NOT NULL,
    claim_token VARCHAR(80), claimed_at BIGINT, attempt INTEGER NOT NULL DEFAULT 0,
    output_asset_id VARCHAR(128), provider_ref VARCHAR(128), failure_code VARCHAR(64),
    created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,
    UNIQUE(user_id, idem), UNIQUE(user_id, billing_ref),
    FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id),
    CHECK(attempt IN (0,1)),
    CHECK(state IN ('queued','claimed','result_ready','succeeded','cancelled','blocked','unknown')),
    CHECK(state NOT IN ('result_ready','succeeded') OR output_asset_id IS NOT NULL)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_uploads` (
    id VARCHAR(80) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, idem CHAR(32) NOT NULL,
    state VARCHAR(16) NOT NULL, storage_key VARCHAR(512) NOT NULL UNIQUE, asset_id VARCHAR(128) NOT NULL UNIQUE,
    sha256 CHAR(64) NOT NULL, byte_length BIGINT NOT NULL, content_type VARCHAR(32) NOT NULL,
    consent_epoch INTEGER NOT NULL, basic_version VARCHAR(80) NOT NULL, face_version VARCHAR(80) NOT NULL,
    moderation_version VARCHAR(80) NOT NULL, moderation_service VARCHAR(80) NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0, recovery_checks INTEGER NOT NULL DEFAULT 0, receipt LONGTEXT,
    source_cleanup_pending INTEGER NOT NULL DEFAULT 0, moderation_cleanup_pending INTEGER NOT NULL DEFAULT 0,
    moderation_cleanup_reference CHAR(32) UNIQUE, moderation_cleanup_extension VARCHAR(4),
    expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,
    UNIQUE(user_id,idem), FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id),
    CHECK(state IN ('staging','queued','claimed','reviewed','ready','rejected','review','unknown','cancelled')),
    CHECK(attempts IN (0,1)), CHECK(source_cleanup_pending IN (0,1)), CHECK(moderation_cleanup_pending IN (0,1)),
    CHECK(byte_length > 0 AND byte_length <= 2097152)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_upload_cleanup` (
    upload_id VARCHAR(80) NOT NULL, kind VARCHAR(16) NOT NULL, storage_key VARCHAR(512) NOT NULL UNIQUE,
    state VARCHAR(24) NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, operation_token CHAR(32),
    delete_status VARCHAR(16) NOT NULL DEFAULT 'not_started', observation VARCHAR(16) NOT NULL DEFAULT 'not_checked',
    next_at BIGINT NOT NULL, delete_started_at BIGINT, checked_at BIGINT, last_absent_at BIGINT, last_present_at BIGINT,
    absent_observations INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,
    PRIMARY KEY(upload_id,kind), FOREIGN KEY(upload_id) REFERENCES `leyanxiu_xpay_production`.`mini_photo_uploads`(id),
    CHECK(kind IN ('source','moderation')), CHECK(state IN ('pending','observing','absent_observed','present','unknown')),
    CHECK(delete_status IN ('not_started','unknown','acknowledged')), CHECK(observation IN ('not_checked','unknown','absent','present')),
    CHECK(attempts >= 0), CHECK(absent_observations >= 0)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_generation` (
      job_id VARCHAR(80) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, spec_hash CHAR(64) NOT NULL,
      policy LONGTEXT NOT NULL, asset_id VARCHAR(128) NOT NULL UNIQUE, output_key VARCHAR(512) NOT NULL UNIQUE,
      marked_sha256 CHAR(64), marked_length BIGINT, marked_type VARCHAR(32), provider_receipt LONGTEXT, review_receipt LONGTEXT,
      moderation_reference CHAR(32) UNIQUE, moderation_extension VARCHAR(4), moderation_cleanup_pending INTEGER NOT NULL DEFAULT 0,
      output_cleanup_pending INTEGER NOT NULL DEFAULT 1, registered INTEGER NOT NULL DEFAULT 0,
      expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,
      FOREIGN KEY(job_id) REFERENCES `leyanxiu_xpay_production`.`mini_photo_jobs`(id), FOREIGN KEY(user_id) REFERENCES `leyanxiu_xpay_production`.`vp_accounts`(user_id),
      CHECK(registered IN (0,1)), CHECK(output_cleanup_pending IN (0,1)), CHECK(moderation_cleanup_pending IN (0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_generation_operations` (
      job_id VARCHAR(80) NOT NULL, step VARCHAR(24) NOT NULL, state VARCHAR(16) NOT NULL,
      token CHAR(32) NOT NULL, attempts INTEGER NOT NULL, started_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,
      PRIMARY KEY(job_id,step), FOREIGN KEY(job_id) REFERENCES `leyanxiu_xpay_production`.`mini_photo_generation`(job_id),
      CHECK(state IN ('started','succeeded','unknown')), CHECK(attempts > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE `leyanxiu_xpay_production`.`mini_photo_generation_cleanup` (
      job_id VARCHAR(80) NOT NULL, kind VARCHAR(16) NOT NULL, storage_key VARCHAR(512) NOT NULL UNIQUE,
      state VARCHAR(24) NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, operation_token CHAR(32),
      delete_status VARCHAR(16) NOT NULL DEFAULT 'not_started', observation VARCHAR(16) NOT NULL DEFAULT 'not_checked',
      next_at BIGINT NOT NULL, checked_at BIGINT, absent_observations INTEGER NOT NULL DEFAULT 0,
      created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,
      PRIMARY KEY(job_id,kind), FOREIGN KEY(job_id) REFERENCES `leyanxiu_xpay_production`.`mini_photo_generation`(job_id),
      CHECK(kind IN ('output','moderation')), CHECK(state IN ('pending','observing','absent_observed','present','unknown')),
      CHECK(delete_status IN ('not_started','unknown','acknowledged')), CHECK(observation IN ('not_checked','unknown','absent','present')),
      CHECK(attempts >= 0), CHECK(absent_observations >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

